    private void nasAudit(Context c,Bundle report)throws Exception{JSONArray devices=DeviceStore.devices(c),results=new JSONArray();java.util.Set<String> seen=new java.util.HashSet<>();for(int i=0;i<devices.length();i++){JSONObject d=devices.getJSONObject(i);String model=d.optString("model");if(!CameraPolicy.supported(model)||d.optInt("state")!=1||!seen.add(model))continue;JSONObject result=new JSONObject().put("model",model);try{JSONObject config=CameraNas.config(MijiaCloud.feature(c,d.getString("id"),"camera.nas.get",new JSONObject()));result.put("config_parsed",true).put("has_share",config.optJSONObject("share")!=null).put("state_known",config.has("state")).put("credentials_logged",false);}catch(Exception e){result.put("config_parsed",false).put("error",CloudDevices.error(e,"NAS读取未完成"));}results.put(result);}report.putString("nas_results",results.toString());report.putBoolean("physical_commands_sent",false);}
